import {readMixingTable,mixingCaseView,createMixingTable,adjustMixingDraft,paintMixingStripe,noteMixingSupport,noteMixingTeaching,mixingSupportFlags,mixingColor,mixingGroups,mixingTableRows} from './mixing-table-core.mjs';
import {mixingScoops,mixingJar,mixingStripe} from './mixing-table-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>{try{return JSON.stringify(x,null,2);}catch{return 'Original data cannot be displayed here.';}};
const button=(label,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const copy={unreadable:'This part of the earlier table cannot be changed safely. Its original stays in your notes. Other readable invitations are still open.',unsupported:'Earlier Mixing Table data are retained in your notes. This format cannot be edited here. Other places are still open.',source:'This table’s earlier source cannot be opened here. Its original stays in your downloadable notes. Other places are still open.',model:'This earlier model’s color picture is unavailable here. Its counts and recorded results stay in your notes. This source cannot be changed or painted here.',helper:'This earlier example cannot be shown here. Your pot is still open, and the original stays in your notes.',section:'Some retained entries cannot be read or matched to an invitation. Their originals stay in your notes.',refusal:'This change could not fit safely in your downloadable notes. Your pot and earlier stripes stay as they were. Download your notes or visit another place.',cap:'This invitation cannot keep another painted observation here. Its first and latest stripes stay in your notes. You can still change the pot or try another invitation.',saveOff:'Saving is off. This table stays in this session. Download your notes if you want a copy.',saveFailure:'This table is in this session, but it could not be saved on this device. Download your notes.'};
const grownupParagraphs=["This is an invented mathematical display toy. Each scoop is one exact model unit. This screen rule does not predict real paint behavior, and taking a scoop back edits a picture rather than unmixing paint. There are no real volume, mass or pigment-strength measurements here.", "The toy display averages the ingredient colors by scoop count. Same proportions give the same screen color under that rule. The converse does not hold: rounding can make different proportions look the same. Matching uses the ordered ingredient amounts, not pixel color. Counts, patterns and comparison text remain available.", "For the unequal 2 white : 3 blue recipe, adding the same positive number to both changes the proportions. Equal 1 : 1 recipes are an exception: adding equally keeps them equal. Adding zero changes nothing. Equivalent recipes can be connected by a fractional multiplier too; 4 : 6 to 6 : 9 is times 1.5.", "Whole Batches already practices complete copies versus an unequal added portion. This table provides a different editable representation: arbitrary two-part compositions, matching relative amounts across different totals, and repairing a near miss. It does not teach the other four benches from the larger proposal, real paint chemistry, unit conversion, graphs or complete ratio mastery.", "Guided starting materials, optional help, familiar invitations and feedback remain visible in the record. A matching construction is a task response using the supplied recipe, not proof of a mental method, independent explanation, physical measuring skill or mastery. Listen to the child's reasons without asking the game to grade speech.", "Only supplied source data, pot counts, first and latest painted observations, paint counts and support reports are stored locally for this explorer. There is no typed answer, recording, upload or automatic sharing. Intermediate stripes are not all retained. Existing notes download, transfer and confirmed reset apply."];
let visits=new WeakMap();
export function resetMixingTableView(state){if(state&&typeof state==='object')visits.delete(state);else visits=new WeakMap();}
function visit(state,explorerId=''){let u=visits.get(state);if(!u||u.explorerId!==explorerId){u={explorerId,id:readMixingTable(state).source?.cases?.[0]?.id,helper:null,step:0,removed:false};visits.set(state,u);}return u;}
const names=p=>p.ingredients.map(i=>i.label);
const counts=(p,a,b)=>`${a} ${names(p)[0]} and ${b} ${names(p)[1]} scoops`;
const comparison=x=>x.comparison==='same'?'Same proportions':'Different proportions';
const fit=x=>x.goal==='fits'?'Fits this invitation':'Keep changing the pot';
const sectionBad=v=>['drafts','observations','support'].some(k=>v[k]?.status!=='ready'||v[k]?.unreadable?.length);
function diagram(p,a,b,model=true,pot=false){return `<div class="mt-diagram">${model?mixingScoops(p,a,b,{pot}):''}<p>${esc(counts(p,a,b))}</p></div>`;}
function stripe(p,x,model){return `${model?mixingStripe(p,x.a,x.b,mixingColor(p,x.a,x.b)):''}<p>${esc(counts(p,x.a,x.b))}</p>${model?`<span class="mt-band-caption">Total scoops: ${x.a+x.b}. ${esc(names(p)[0])}: ${x.a}; ${esc(names(p)[1])}: ${x.b}. The patterns name the ingredients.</span>`:''}`;}
function helperAvailable(v,c,type){return v.modelSupported&&c.draftReadable&&c.supportReadable&&(type==='teaching'?!!v.helpers.teaching&&typeof v.root.teaching==='boolean':type==='example'?!!v.helpers.example:type==='bridge'?c.recordReadable:['clue','groups','table'].includes(type));}
function helpers(v,u,c){if(!u.helper||!helperAvailable(v,c,u.helper))return '';const type=u.helper,p=c.pair,{a,b}=c.counts;let title='',body='';
 if(type==='clue'){title='Clue';body=`<p>${esc(c.case.clue)}</p>`;}
 if(type==='teaching'||type==='example'){const h=v.helpers[type],s=h?.steps[u.step];title=h?.title||'Earlier example';if(s){const pair=v.source.pairs.find(p=>p.id===s.pairId);body=`<div class="mt-helper-diagrams">${s.diagrams.map(d=>`<figure><figcaption>${esc(d.label)}</figcaption>${diagram(pair,d.a,d.b)}</figure>`).join('')}</div><p>${esc(s.text)}</p><nav>${button('Previous step',`data-mt-step="-1" ${u.step===0?'disabled':''}`)}${button('Next step',`data-mt-step="1" ${u.step===h.steps.length-1?'disabled':''}`)}</nav><p>This worked example leaves your own pot unchanged. You can return at any step.</p>`;}else body=`<p>${esc(copy.helper)}</p>`;}
 if(type==='groups'){title='Whole sample groups in this pot';const g=mixingGroups(c.case,a,b);body=`<p>${g.count} whole ${g.count===1?'group':'groups'}</p>${g.count?`<div class="mt-groups">${Array.from({length:g.count},()=>diagram(p,c.case.sample.a,c.case.sample.b)).join('')}</div>`:'<p>No complete sample group fits yet. Your scoops are still shown.</p>'}<p>Left over: ${esc(counts(p,g.a,g.b))}.</p>${diagram(p,g.a,g.b)}<p>This view makes whole sample groups. Leftovers are kept, not rounded or removed.</p>`;}
 if(type==='table'){title='Same recipe, several amounts';body=`<table><thead><tr><th>Recipe row</th>${names(p).map(n=>`<th>${esc(n)} scoops</th>`).join('')}</tr></thead><tbody>${mixingTableRows(c.case).map(r=>`<tr><th>${['','Sample','Two groups','Three groups','Four groups'][r.multiplier]}</th><td>${r.a}</td><td>${r.b}</td></tr>`).join('')}<tr><th>Your pot now</th><td>${a}</td><td>${b}</td></tr></tbody></table><p>The supplied rows repeat the whole recipe. Your pot’s row shows what you made; it may differ.</p><p>${a?`${esc(names(p)[1])} divided by ${esc(names(p)[0])}: ${b}/${a}. This row describes your pot.`:'Division by zero is not defined. Use the ordered counts and the picture instead.'}</p>`;}
 if(type==='bridge'){title='A complete group in another game';body=`<h3>Frozen sample from this table</h3>${diagram(p,c.case.sample.a,c.case.sample.b)}<h3>${c.latest?'Latest painted counts':'Current pot, not painted'}</h3>${diagram(p,c.latest?.a??a,c.latest?.b??b)}<p>Here is this table’s saved sample and your ${c.latest?'painted stripe':'current unpainted pot'}. Whole Batches repeats a complete recipe too, using separate preparation jars. This toy makes one combined color pot. The amounts and jobs in the two games are different. No answer travels with this link.</p><a href="#cafe/batches">Visit Whole Batches</a> <a href="#studio/mixing" data-mt-return>Return to the Mixing Table</a>`;}
 return `<section class="mt-helper"><h2 id="mt-helper-focus" tabindex="-1">${esc(title)}</h2>${body}${button('Back to my pot','data-mt-close')}</section>`;
}
function controls(v,c){return `<div class="mt-help" aria-label="Optional help">${[['teaching','Try one group'],['clue','Clue'],['example','Another example'],['groups','Show groups'],['table','Show a table']].filter(([id])=>helperAvailable(v,c,id)).map(([id,label])=>button(label,`data-mt-helper="${id}"`)).join('')}${v.modelSupported&&c.draftReadable&&c.supportReadable?hearButton([c.case.prompt,...c.case.guided,`The sample recipe: ${counts(c.pair,c.case.sample.a,c.case.sample.b)}`,`Your pot: ${counts(c.pair,c.counts.a,c.counts.b)}`,!c.recordReadable?copy.unreadable:c.latest?`${c.draftStatus==='changed'?'Pot changed since this stripe. ':''}Your painted stripe: ${counts(c.pair,c.latest.a,c.latest.b)}. ${comparison(c.latest)}. ${fit(c.latest)}.`:'No stripe painted here yet.'].join('. '),'Hear'):''}${v.modelSupported&&c.supportReadable?button('Working together',`data-mt-together aria-pressed="${c.support?.together===true}"`):''}</div><p>Choose Working together if a grown-up is helping with this invitation. It is your report, not a test.</p>${v.modelSupported&&(!v.helpers.teaching||!v.helpers.example)?`<p>${esc(copy.helper)}</p>`:''}`;}
function task(v,u){const c=mixingCaseView(v,u.id),p=c.pair;if(!c.case||!p)return `<p>${esc(copy.unreadable)}</p>`;const {a,b}=c.counts||{a:0,b:0},model=v.modelSupported,editable=model&&c.draftReadable,index=v.source.cases.findIndex(x=>x.id===u.id);
return `<h2 id="mt-focus" tabindex="-1">${esc(c.case.title)}</h2><p class="mt-goal">${esc(c.case.prompt)}</p>${c.case.guided.length?`<div class="mt-guided"><strong>Guided example</strong><ol>${c.case.guided.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div>`:''}${!model?`<p>${esc(copy.model)}</p>`:''}${!c.draftReadable||!c.recordReadable||!c.supportReadable?`<p>${esc(copy.unreadable)}</p>`:''}<div class="mt-workbench"><section class="mt-sample"><h3>The sample recipe</h3>${stripe(p,c.case.sample,model)}${model?mixingScoops(p,c.case.sample.a,c.case.sample.b):''}<p>${c.case.sample.a} ${esc(names(p)[0])} for every ${c.case.sample.b} ${esc(names(p)[1])}</p><p>Ratio order: ${esc(names(p).join(' : '))}</p></section><div class="mt-jars">${p.ingredients.map((ingredient,n)=>{const key=n?'b':'a',count=n?b:a;return `<section class="mt-jar">${model?mixingJar(ingredient):''}<h3>${esc(ingredient.label)} <span data-mt-count="${key}">${c.draftReadable?count:"?"}</span></h3>${button(`Add one ${ingredient.label}`,`data-mt-adjust="${key}" data-delta="1" ${!editable||count>=24?'disabled':''}`)}${button(`Take one ${ingredient.label} back`,`data-mt-adjust="${key}" data-delta="-1" ${!editable||count<=0?'disabled':''}`)}${c.draftReadable&&count===0?`<p>There are no ${esc(ingredient.label)} scoops to take back.</p>`:c.draftReadable&&count===24?'<p>This picture table holds up to 24 scoops of each ingredient. Take one back to make room.</p>':''}</section>`;}).join('')}</div><section class="mt-pot"><h3>Your pot</h3>${c.draftReadable?`${c.suppliedStart?'<p class="mt-start-label">Supplied starting pot</p>':''}${diagram(p,a,b,model,true)}<p>${a+b?`${a+b} scoops in all`:'Empty pot'}</p>`:`<p>${esc(copy.unreadable)}</p>`}${button('Paint a stripe',`data-mt-paint ${!editable||!c.recordReadable||!c.supportReadable||typeof v.root.teaching!=='boolean'||a+b===0?'disabled':''}`,true)}<p class="mt-draft-status">${!c.draftReadable?'Earlier pot cannot be read.':!c.recordReadable?esc(copy.unreadable):a+b===0?'Add a scoop before painting. An empty pot has no recipe to compare.':c.draftStatus==='changed'?'Your pot changed. Paint when you want to test this version.':!c.latest?'No stripe painted here yet. Your pot is ready to change.':'Your pot stays editable.'}</p>${u.removed?'<p>Taking a scoop back edits the picture. It does not show how to separate real mixed paint.</p>':''}</section><section class="mt-painted" data-mt-stripe><h3 id="mt-stripe-focus" tabindex="-1">Your painted stripe</h3>${c.latest?`${c.draftStatus==='changed'?'<strong>Pot changed since this stripe</strong>':''}${stripe(p,c.latest,model)}<p><strong>${comparison(c.latest)}</strong> · ${fit(c.latest)}</p>${c.latest.a===0||c.latest.b===0?'<p>One ingredient only. Its ordered counts are still shown.</p>':''}<details><summary>What these amounts show</summary><p>${esc(c.case.feedback[c.latest.feedbackCode])}</p><h4>Supplied goal example</h4><p>Here is one pot that fits this invitation. It is an example, not a description of your pot.</p><p>${esc(c.case.explanation)}</p><p>${esc(c.case.reasonPrompt)}</p><p>Tell a grown-up in your own words or point to a group. Nothing spoken is recorded or marked.</p><p>Your pot stays as you made it. Add or take back a scoop, then paint again. Your first stripe stays in your notes.</p></details>`:c.recordReadable?'<p>No stripe painted here yet.</p>':`<p>${esc(copy.unreadable)}</p>`}</section></div><p class="mt-model-notice">Picture paint. Compare the scoop proportions.</p><details><summary>How this picture works</summary><p>${esc(v.source.notice)}</p></details><nav class="mt-navigation">${button('Previous invitation',`data-mt-next="-1" ${index===0?'disabled':''}`)}${button('Next invitation',`data-mt-next="1" ${index===v.source.cases.length-1?'disabled':''}`)}</nav>${controls(v,c)}${helpers(v,u,c)}${helperAvailable(v,c,'bridge')?button('Take this group to Whole Batches','data-mt-helper="bridge"'):''}<nav class="mt-invitations" aria-label="Choose an invitation"><h3>Choose an invitation</h3>${v.source.cases.map(x=>button(x.title,`data-mt-case="${esc(x.id)}" aria-current="${x.id===u.id?'true':'false'}"`)).join('')}</nav>`;
}
export function mixingTableEntry(){return `<aside class="mt-entry"><h3>The Mixing Table</h3><p>Build a recipe with scoops. Change the amounts and paint a stripe.</p><a href="#studio/mixing">Visit the Mixing Table</a></aside>`;}
export function mixingTablePage(state,explorerId=''){const v=readMixingTable(state),u=visit(state,explorerId);let content;if(v.status==='missing')content=`<h2 id="mt-focus" tabindex="-1">Scoop, change, and paint a stripe.</h2><p>Can a bigger pot keep the same recipe?</p><p>Your pots stay editable. Notes keep your first stripe, latest retry, and number of paints, not every stripe in between.</p>${button('Open the table','data-mt-start',true)}`;else if(v.status!=='ready')content=`<h2 id="mt-focus" tabindex="-1">Earlier work is retained</h2><p>${esc(v.status==='unsupported'?copy.unsupported:copy.source)}</p>`;else {if(!v.source.cases.some(c=>c.id===u.id)){u.id=v.source.cases[0].id;u.helper=null;}content=`${typeof v.root.teaching!=='boolean'?'<p>Earlier teaching context cannot be read. You can change this pot, but cannot paint another stripe here.</p>':''}${sectionBad(v)?`<p>${esc(copy.section)}</p>`:''}${task(v,u)}<details class="mt-grownup"><summary>Grown-up guide</summary><p>${esc(v.source.origin)}</p>${grownupParagraphs.map(t=>`<p>${esc(t)}</p>`).join('')}<p>The game's confirmed reset removes this explorer's table records from this device. It does not remove another explorer's work or files already downloaded.</p></details>`;}return `<section data-mixing-table-view><header class="mt-heading"><a href="#numbers">← Number Garden</a><h1>The Mixing Table</h1></header><nav class="mt-family" aria-label="Mixing Table tools"><a href="#studio/mixing" aria-current="page">Shade pots</a><a href="#studio/mixing/bars">Equal blocks</a></nav><p id="mt-status" role="status" aria-live="polite" tabindex="-1"></p>${content}<p>${button('Download our notes','data-mt-download')} <a href="#notes">Grown-up notes</a></p></section>`;}
function context(c){return `${c.case.guided.length?'<p>Guided example shown with this invitation</p>':''}<p>${c.case.initial.a+c.case.initial.b?`Supplied starting pot: ${esc(counts(c.pair,c.case.initial.a,c.case.initial.b))}`:'Supplied start: an empty pot'}</p>`;}
function observation(c,x,label,model){return `<section><h4>${label}</h4>${context(c)}<p>Recorded stripe counts: ${esc(counts(c.pair,x.a,x.b))}.</p>${model?mixingStripe(c.pair,x.a,x.b,mixingColor(c.pair,x.a,x.b)):''}<p>Recorded comparison: ${comparison(x)}. Invitation fit: ${fit(x)}.</p><p>Supplied feedback: ${esc(c.case.feedback[x.feedbackCode])}</p><ul>${mixingSupportFlags.map((flag,n)=>`<li>${['Clue opened','Worked example opened','Groups shown','Table shown','Hear requested','Working together reported'][n]}: ${x.supportBefore[flag]?'Recorded before this paint':'Not recorded before this paint'}</li>`).join('')}<li>Teaching opened: ${x.teachingBefore?'Recorded before this paint':'Not recorded before this paint'}</li><li>Feedback available for this paint: ${x.afterFeedback?'yes':'no'}</li></ul></section>`;}
export function mixingTableNotes(state){const v=readMixingTable(state);if(v.status==='missing')return '';return `<details class="panel mt-notes"><summary>The Mixing Table</summary><p>Saved pots are ungraded. First paint and latest retry are retained; intermediate stripes are not all retained. Supplied recipes, starting pots and guidance are context, not independent mastery evidence.</p>${v.status==='ready'?`<p>${esc(v.source.title)}. ${esc(v.source.origin)}</p><p>${esc(v.source.notice)}</p>${!v.modelSupported?`<p>${esc(copy.model)}</p>`:''}${typeof v.root.teaching!=='boolean'?'<p>Earlier teaching context cannot be read. Its original stays in these notes.</p>':''}${sectionBad(v)?`<p>${esc(copy.section)}</p>`:''}${v.source.cases.map(item=>{const c=mixingCaseView(v,item.id);return `<section><h3>${esc(item.title)}</h3><p>Frozen sample: ${esc(counts(c.pair,item.sample.a,item.sample.b))}. Ratio order: ${esc(names(c.pair).join(' : '))}.</p><p>${esc(item.prompt)}</p>${context(c)}<p>Ungraded pot: ${c.draftReadable?esc(counts(c.pair,c.counts.a,c.counts.b)):esc(copy.unreadable)}.</p><p>${c.suppliedStart?'Supplied starting pot. ':''}${c.draftStatus==='changed'?'Pot changed since this stripe.':''}</p>${c.record?`<p>${c.record.paintCount} ${c.record.paintCount===1?'paint · First paint here':'paints · Painted before here'}</p>${observation(c,c.record.first,'First paint',v.modelSupported)}${c.record.latest?observation(c,c.record.latest,'Latest retry',v.modelSupported):''}`:c.recordReadable?'<p>No paint recorded here</p>':`<p>${esc(copy.unreadable)}</p>`}${!c.supportReadable?`<p>Retained support cannot be read. ${esc(copy.unreadable)}</p>`:''}</section>`;}).join('')}`:`<p>${esc(v.status==='unsupported'?copy.unsupported:copy.source)}</p>`}<details><summary>Original saved Mixing Table data</summary><pre>${esc(json(state.mixingTable))}</pre></details></details>`;}
export function bindMixingTable(state,{notebook=()=>state,explorerId=()=>'',isActive=()=>true,save,render,focus,canExport,download,stopSpeech,stopSound}={}){
 const host=document.querySelector('[data-mixing-table-view]');if(!host)return;const u=visit(state,explorerId()),boundExplorer=explorerId(),boundCase=u.id,boundSource=json(readMixingTable(state).source),boundHelper=u.helper,boundStep=u.step;let boundRoot=state.mixingTable;
 const live=el=>el.isConnected&&host.isConnected&&!el.closest('[hidden]')&&el.getClientRects().length>0&&notebook()===state&&explorerId()===boundExplorer&&isActive()&&window.location.hash==='#studio/mixing'&&visits.get(state)===u&&u.id===boundCase&&u.helper===boundHelper&&u.step===boundStep&&state.mixingTable===boundRoot&&json(readMixingTable(state).source)===boundSource;
 const status=(message,takeFocus=false)=>{const box=host.querySelector('#mt-status');if(box){box.textContent=message;if(takeFocus)box.focus();}};
 const refusal=r=>r.code==='paint-count-cap'?copy.cap:r.code==='report-safety'?copy.refusal:copy.unreadable;
 const persist=()=>{try{const r=save?.();return r?.enabled===false?copy.saveOff:r?.ok===false?copy.saveFailure:'';}catch{return copy.saveFailure;}};
 const redraw=(target='#mt-focus',message='',write=false)=>{const note=write?persist():'';stopSpeech?.();stopSound?.();render?.();const next=document.querySelector('[data-mixing-table-view]');if(!next)return;const box=next.querySelector('#mt-status');if(box)box.textContent=[message,note].filter(Boolean).join(' ');if(focus)focus(target);else next.querySelector(target)?.focus();};
 const bind=(selector,fn)=>host.querySelectorAll(selector).forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}fn(el,event);}));
 bind('[data-mt-start]',()=>{const r=createMixingTable(state,canExport);if(!r.ok)return status(refusal(r),true);u.id=readMixingTable(state).source.cases[0].id;redraw('#mt-focus','',r.changed);});
 bind('[data-mt-download]',()=>download?.());
 bind('[data-mt-case]',el=>{u.id=el.dataset.mtCase;u.helper=null;u.removed=false;redraw();});
 bind('[data-mt-next]',el=>{const cases=readMixingTable(state).source.cases,index=cases.findIndex(c=>c.id===u.id),next=cases[index+Number(el.dataset.mtNext)];if(next){u.id=next.id;u.helper=null;u.removed=false;redraw();}});
 bind('[data-mt-adjust]',el=>{const key=el.dataset.mtAdjust,delta=Number(el.dataset.delta),r=adjustMixingDraft(state,u.id,key,delta,canExport);if(!r.ok)return status(refusal(r),true);if(delta<0)u.removed=true;if(r.changed){const n=mixingCaseView(state,u.id).counts[key],nextDelta=n===0?1:n===24?-1:delta;redraw(`[data-mt-adjust="${key}"][data-delta="${nextDelta}"]`,'Your pot changed. Paint when you want to test this version.',true);}});
 bind('[data-mt-paint]',()=>{const r=paintMixingStripe(state,u.id,canExport);if(!r.ok)return status(refusal(r),true);if(r.changed)redraw('#mt-stripe-focus','',true);else {status('This is the stripe already shown. Change the pot or use another idea before painting a new version.');host.querySelector('#mt-stripe-focus')?.focus();}});
 bind('[data-mt-together]',()=>{const r=noteMixingSupport(state,u.id,'together',canExport);if(!r.ok)return status(refusal(r),true);if(r.changed)redraw('[data-mt-together]','Working together reported.',true);});
 bind('[data-mt-helper]',el=>{const type=el.dataset.mtHelper,v=readMixingTable(state),c=mixingCaseView(v,u.id);if(!helperAvailable(v,c,type))return status(copy.helper,true);let r=type==='bridge'?{ok:true,changed:false}:type==='teaching'?noteMixingTeaching(state,canExport):noteMixingSupport(state,u.id,type,canExport);if(!r.ok)return status(refusal(r),true);u.helper=type;u.step=0;redraw('#mt-helper-focus','',r.changed);});
 bind('[data-mt-step]',el=>{const h=readMixingTable(state).helpers[u.helper];if(!h)return status(copy.helper,true);u.step=Math.max(0,Math.min(h.steps.length-1,u.step+Number(el.dataset.mtStep)));redraw('#mt-helper-focus');});
 bind('[data-mt-close]',()=>{const type=u.helper;u.helper=null;redraw(`[data-mt-helper="${type}"]`);});
 bind('[data-mt-return]',(el,event)=>{event.preventDefault();event.stopPropagation();u.helper=null;redraw();});
 host.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}const c=mixingCaseView(state,u.id);if(!c.modelSupported||!c.draftReadable||!c.supportReadable){event.preventDefault();event.stopImmediatePropagation();status(copy.unreadable,true);return;}const r=noteMixingSupport(state,u.id,'narration',canExport);if(!r.ok){event.preventDefault();event.stopImmediatePropagation();status(refusal(r),true);return;}if(r.changed){boundRoot=state.mixingTable;const note=persist();if(note)status(note);}},true));
}
